; t03_branch -- BR.COND not taken and taken
; Layer-3 timing program (generated by conformance/make_timing.py: edit that, not this file).
; Markers are CSR writes to RES + k; the intervals between them are what is measured. Predictions: TIMING.md
.include "conf_defs.inc"
.main
.assume MAIN_SCRATCHPAD[0..31] defined
    MOV CONST(2, 2) -> MAIN_SCRATCHPAD[0..1]
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV CONST(1, 2) -> MAIN_SCRATCHPAD[2..3]
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    ALU CMP.EQ unsigned                        ; 2 == 1 is false: the branches below are not taken
    EXEC_CSR WRITE8 RES + 0, 0x40            ; marker 0
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    EXEC_CSR WRITE8 RES + 1, 0x41            ; marker 1
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    BR.COND ALU_CMP_TRUE, never
    EXEC_CSR WRITE8 RES + 2, 0x42            ; marker 2
    EXEC_CSR WRITE8 RES + 3, 0x43            ; marker 3
    JMP j0
j0:
    JMP j1
j1:
    JMP j2
j2:
    JMP j3
j3:
    EXEC_CSR WRITE8 RES + 4, 0x44            ; marker 4
    JMP j4
j4:
    JMP j5
j5:
    JMP j6
j6:
    JMP j7
j7:
    JMP j8
j8:
    JMP j9
j9:
    JMP j10
j10:
    JMP j11
j11:
    JMP j12
j12:
    JMP j13
j13:
    JMP j14
j14:
    JMP j15
j15:
    EXEC_CSR WRITE8 RES + 5, 0x45            ; marker 5
    JMP past
never:
    EXEC_CSR WRITE8 RES + 15, 0xBD           ; (never reached)
past:
    EXEC_CSR WRITE8 RES_DONE, 0xA5
done:
    JMP done
